cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Returning customer in the Bronze tier is charged 9500 cents for a 10000 cent basket
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_subtotal_less_the_reduction_of_their_loyalty_tier(
        LoyaltyTier loyaltyTier, int subtotalCents, int expectedChargedCents)
    {
        var calculateLoyaltyDiscount = new CalculateLoyaltyDiscount();

        var quote = calculateLoyaltyDiscount.Handle(
            new CalculateLoyaltyDiscountQuery(subtotalCents, loyaltyTier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
cd tests/CheckoutPricing.UnitTest && dotnet test --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > /tmp/red.out 2>&1; echo $? > /tmp/red.exit; tail -25 /tmp/red.out; cat /tmp/red.exit

